pub proof fn always_implies_forall_intro<T, A>(spec: TempPred<T>, p: TempPred<T>, a_to_q: spec_fn(A) -> TempPred<T>)
    requires forall |a: A| #[trigger] spec.entails(always(p.implies(a_to_q(a)))),
    ensures spec.entails(always(p.implies(tla_forall(a_to_q)))),
{
    let a_to_p = |a: A| always(p.implies(a_to_q(a)));

    // From the premise, we can entail the `tla_forall` of the family of always-predicates.
    assert(spec.entails(tla_forall(a_to_p))) by {
        spec_entails_tla_forall(spec, a_to_p);
    };

    // And we can rewrite that `tla_forall` back into `always(p.implies(tla_forall(a_to_q)))`.
    assert(spec.entails(always(p.implies(tla_forall(a_to_q))))) by {
        assert(
            spec.entails(tla_forall(a_to_p))
                == spec.entails(always(p.implies(tla_forall(a_to_q))))
        );
        // The previous assertion supplies `spec.entails(tla_forall(a_to_p))`.
        spec_entails_tla_forall(spec, a_to_p);
        // Use the equality guaranteed by the other helper lemma.
        tla_forall_always_implies_equality2(p, a_to_q);
    };
}


}

